# Claus que se substitueixen o es fusionen; la resta són noves.
SPECIAL = ('itinerary1', 'conds', 'docsMeta0', 'docsBody0')


def apply(C):
    """Aplica FITXA sobre window.COPY (dict de quatre idiomes)."""
    for L, F in FITXA.items():
        c = C[L]
        for k, v in F.items():
            if k not in SPECIAL: c[k] = v
        c['itinerary'][0] = F['itinerary1']
        base = c['conds'][:7]
        new = [F['conds'][i] if i < len(F['conds']) and F['conds'][i] else base[i] for i in range(7)] + F['conds'][7:]
        c['conds'] = new
        c['docs'][0][1], c['docs'][0][2] = F['docsMeta0'], F['docsBody0']
        # numeració de les seccions amb el nou ordre: nivell, experiència, etapes, programa, preu, preparació, preguntes, documents
        for key, n in (('storyLabel', 2), ('routeLabel', 3), ('journeyLabel', 4), ('priceLabel', 5), ('prepLabel', 6), ('faqLabel', 7), ('docsLabel', 8)):
            c[key] = re.sub(r'^\d\d', f'{n:02d}', c[key])
    return C
